export type WebVideoPlayerSource = {
    readonly kind: 'restgo';
    readonly videoId: string;
} | {
    readonly kind: 'url';
    readonly url: string;
    readonly format: 'hls' | 'dash';
};

export type WebVideoPlayerState = 'idle' | 'loading' | 'loaded' | 'playing' | 'paused' | 'ended' | 'error' | 'disposed';

export type WebVideoPlayerQuality = 'auto' | number;

export type WebVideoPlayerObjectFit = 'contain' | 'cover' | 'fill' | 'none' | 'scale-down';

export interface WebVideoPlayerLoadOptions {
    readonly signal?: AbortSignal;
    readonly startTime?: number;
}

export interface WebVideoPlayerRestGoOptions extends WebVideoPlayerLoadOptions {
    readonly public?: boolean;
}

export interface WebVideoPlayerUrlOptions extends WebVideoPlayerLoadOptions {
    readonly format?: 'hls' | 'dash';
}

export interface WebVideoPlayerAvailableQuality {
    readonly quality: number;
    readonly width: number;
    readonly height: number;
    readonly codecs: string;
}

export interface WebVideoPlayerLoadedEventDetail {
    readonly source: WebVideoPlayerSource;
    readonly duration: number;
    readonly availableQualities: readonly WebVideoPlayerAvailableQuality[];
}

export interface WebVideoPlayerTimeEventDetail {
    readonly currentTime: number;
    readonly duration: number;
}

export interface WebVideoPlayerBufferingEventDetail {
    readonly buffering: boolean;
}

export interface WebVideoPlayerQualityEventDetail {
    readonly requested: WebVideoPlayerQuality;
    readonly current: number | null;
}

export interface WebVideoPlayerBufferedRange {
    readonly start: number;
    readonly end: number;
}

/** One real Shaka player per component element, shared by mounting and generated instances. */
export class WebVideoPlayer extends WebComponent {
    #private;
    constructor(element: HTMLElement);
    get source(): WebVideoPlayerSource | null;
    set source(value: WebVideoPlayerSource | null);
    get controls(): boolean;
    set controls(value: boolean);
    get autoplay(): boolean;
    set autoplay(value: boolean);
    get muted(): boolean;
    set muted(value: boolean);
    get loop(): boolean;
    set loop(value: boolean);
    get playsInline(): boolean;
    set playsInline(value: boolean);
    get volume(): number;
    set volume(value: number);
    get playbackRate(): number;
    set playbackRate(value: number);
    get objectFit(): WebVideoPlayerObjectFit;
    set objectFit(value: WebVideoPlayerObjectFit);
    get poster(): string;
    set poster(value: string);
    get enabled(): boolean;
    set enabled(value: boolean);
    get quality(): WebVideoPlayerQuality;
    set quality(value: WebVideoPlayerQuality);
    get state(): WebVideoPlayerState;
    get duration(): number;
    get currentTime(): number;
    get buffered(): readonly WebVideoPlayerBufferedRange[];
    get availableQualities(): readonly WebVideoPlayerAvailableQuality[];
    get currentQuality(): number | null;
    get isPlaying(): boolean;
    get error(): Error | null;
    LoadRestGo(videoId: string, options?: WebVideoPlayerRestGoOptions): Promise<void>;
    LoadUrl(url: string, options?: WebVideoPlayerUrlOptions): Promise<void>;
    Play(): Promise<void>;
    Pause(): void;
    Stop(): void;
    Seek(seconds: number): void;
    SetQuality(value: WebVideoPlayerQuality): void;
    Unload(): Promise<void>;
    dispose(): void;
    set onLoaded(handler: WebComponentEventHandler<this> | null);
    set onPlay(handler: WebComponentEventHandler<this> | null);
    set onPause(handler: WebComponentEventHandler<this> | null);
    set onEnded(handler: WebComponentEventHandler<this> | null);
    set onTimeUpdate(handler: WebComponentEventHandler<this> | null);
    set onBuffering(handler: WebComponentEventHandler<this> | null);
    set onQualityChange(handler: WebComponentEventHandler<this> | null);
    set onError(handler: WebComponentEventHandler<this> | null);
}
